import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cpp_src = r"""
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_fp16.h>
#include <mma.h>
#include <cmath>
namespace {
using namespace nvcuda;
constexpr int BR = 16;       // query rows per block (one 16-row mma band)
constexpr int BN = 64;       // keys per inner tile (4 x 16-wide n-fragments)
constexpr int THREADS = 128; // 4 warps, one per 16-wide key fragment
constexpr int NWARPS = THREADS / 32;
__global__ void fused_sdpa_kernel(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    const __half* __restrict__ V,
    __half* __restrict__ out,
    const int B,
    const int H,
    const int L,
    const int D,
    const float scale) {
  extern __shared__ char smem_raw[];
  float* acc = reinterpret_cast<float*>(smem_raw);          // BR * D
  float* sS = acc + BR * D;                                  // BR * BN
  __half* sP = reinterpret_cast<__half*>(sS + BR * BN);      // BR * BN
  float* m = reinterpret_cast<float*>(sP + BR * BN);         // BR
  float* l = m + BR;                                         // BR
  float* alpha = l + BR;                                     // BR
  const int tid = threadIdx.x;
  const int warp = tid >> 5;
  const int bh = blockIdx.y;
  const int q0 = blockIdx.x * BR;
  const size_t bh_stride = static_cast<size_t>(L) * D;
  const __half* Qb = Q + static_cast<size_t>(bh) * bh_stride;
  const __half* Kb = K + static_cast<size_t>(bh) * bh_stride;
  const __half* Vb = V + static_cast<size_t>(bh) * bh_stride;
  __half* Ob = out + static_cast<size_t>(bh) * bh_stride;
  if (tid < BR) {
    m[tid] = -INFINITY;
    l[tid] = 0.0f;
    alpha[tid] = 0.0f;
  }
  for (int idx = tid; idx < BR * D; idx += THREADS) {
    acc[idx] = 0.0f;
  }
  __syncthreads();
  for (int k0 = 0; k0 < L; k0 += BN) {
    // ---- S = Q_tile @ K_tile^T via tensor cores (fp16 in, fp32 acc) ----
    {
      const int nf = warp;  // BN/16 == NWARPS == 4, one n-fragment per warp
      wmma::fragment<wmma::accumulator, 16, 16, 16, float> c;
      wmma::fill_fragment(c, 0.0f);
      for (int kc = 0; kc < D; kc += 16) {
        wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::row_major> af;
        wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::col_major> bf;
        wmma::load_matrix_sync(af, Qb + static_cast<size_t>(q0) * D + kc, D);
        // col_major B reads row-major K as K^T: elem(kk,j)=K[k0+nf*16+j][kc+kk]
        wmma::load_matrix_sync(bf, Kb + static_cast<size_t>(k0 + nf * 16) * D + kc, D);
        wmma::mma_sync(c, af, bf, c);
      }
      wmma::store_matrix_sync(sS + nf * 16, c, BN, wmma::mem_row_major);
    }
    __syncthreads();
    // ---- online softmax update for this key tile ----
    if (tid < BR) {
      const int base = tid * BN;
      const float old_m = m[tid];
      const float old_l = l[tid];
      float new_m = old_m;
      #pragma unroll
      for (int j = 0; j < BN; ++j) {
        const float sc = sS[base + j] * scale;
        new_m = sc > new_m ? sc : new_m;
      }
      const float a = (old_l == 0.0f) ? 0.0f : __expf(old_m - new_m);
      float new_l = old_l * a;
      #pragma unroll
      for (int j = 0; j < BN; ++j) {
        const float e = __expf(sS[base + j] * scale - new_m);
        sP[base + j] = __float2half(e);
        new_l += e;
      }
      m[tid] = new_m;
      l[tid] = new_l;
      alpha[tid] = a;
    }
    __syncthreads();
    // rescale running accumulator
    for (int idx = tid; idx < BR * D; idx += THREADS) {
      acc[idx] *= alpha[idx / D];
    }
    __syncthreads();
    // ---- acc += P_tile @ V_tile via tensor cores, split over head dim ----
    for (int nfrag = warp; nfrag < (D >> 4); nfrag += NWARPS) {
      const int n0 = nfrag << 4;
      wmma::fragment<wmma::accumulator, 16, 16, 16, float> c;
      wmma::load_matrix_sync(c, acc + n0, D, wmma::mem_row_major);
      #pragma unroll
      for (int kf = 0; kf < BN; kf += 16) {
        wmma::fragment<wmma::matrix_a, 16, 16, 16, __half, wmma::row_major> af;
        wmma::fragment<wmma::matrix_b, 16, 16, 16, __half, wmma::row_major> bf;
        wmma::load_matrix_sync(af, sP + kf, BN);
        wmma::load_matrix_sync(bf, Vb + static_cast<size_t>(k0 + kf) * D + n0, D);
        wmma::mma_sync(c, af, bf, c);
      }
      wmma::store_matrix_sync(acc + n0, c, D, wmma::mem_row_major);
    }
    __syncthreads();
  }
  for (int idx = tid; idx < BR * D; idx += THREADS) {
    const int r = idx / D;
    const float inv_l = 1.0f / l[r];
    Ob[static_cast<size_t>(q0) * D + idx] = __float2half_rn(acc[idx] * inv_l);
  }
}
inline size_t smem_bytes(const int D) {
  return static_cast<size_t>(BR) * D * sizeof(float) +
         static_cast<size_t>(BR) * BN * sizeof(float) +
         static_cast<size_t>(BR) * BN * sizeof(__half) +
         static_cast<size_t>(3 * BR) * sizeof(float);
}
}  // namespace
torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
  TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q, K, V must be CUDA tensors");
  TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf,
              "Q, K, V must be float16");
  TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q, K, V must be 4D");
  TORCH_CHECK(Q.size(0) == K.size(0) && Q.size(0) == V.size(0), "batch mismatch");
  TORCH_CHECK(Q.size(1) == K.size(1) && Q.size(1) == V.size(1), "head mismatch");
  TORCH_CHECK(Q.size(2) == K.size(2) && Q.size(2) == V.size(2), "sequence mismatch");
  TORCH_CHECK(Q.size(3) == K.size(3) && Q.size(3) == V.size(3), "embedding mismatch");
  TORCH_CHECK(Q.is_contiguous() && K.is_contiguous() && V.is_contiguous(), "Q, K, V must be contiguous");
  const int B = static_cast<int>(Q.size(0));
  const int H = static_cast<int>(Q.size(1));
  const int L = static_cast<int>(Q.size(2));
  const int D = static_cast<int>(Q.size(3));
  TORCH_CHECK(L % BR == 0, "sequence length must be divisible by 16");
  TORCH_CHECK(L % BN == 0, "sequence length must be divisible by 64");
  TORCH_CHECK(D % 16 == 0, "embedding dimension must be divisible by 16");
  auto out = at::empty_like(Q);
  const float scale = static_cast<float>(1.0 / std::sqrt(static_cast<double>(D)));
  const size_t smem = smem_bytes(D);
  const auto* prop = at::cuda::getCurrentDeviceProperties();
  TORCH_CHECK(smem <= static_cast<size_t>(prop->sharedMemPerBlockOptin),
              "required shared memory exceeds device opt-in limit");
  const cudaError_t attr_err = cudaFuncSetAttribute(
      reinterpret_cast<const void*>(fused_sdpa_kernel),
      cudaFuncAttributeMaxDynamicSharedMemorySize,
      static_cast<int>(smem));
  TORCH_CHECK(attr_err == cudaSuccess, cudaGetErrorString(attr_err));
  dim3 grid(L / BR, B * H);
  dim3 block(THREADS);
  auto stream = at::cuda::getCurrentCUDAStream().stream();
  fused_sdpa_kernel<<<grid, block, smem, stream>>>(
      reinterpret_cast<const __half*>(Q.data_ptr<at::Half>()),
      reinterpret_cast<const __half*>(K.data_ptr<at::Half>()),
      reinterpret_cast<const __half*>(V.data_ptr<at::Half>()),
      reinterpret_cast<__half*>(out.data_ptr<at::Half>()),
      B, H, L, D, scale);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return out;
}
"""

_ext = load_inline(
    name="fused_sdpa_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["sdpa_forward"],
    extra_cuda_cflags=["-O3", "-std=c++17"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return _ext.sdpa_forward(Q.contiguous(), K.contiguous(), V.contiguous())

