  float* acc = reinterpret_cast<float*>(smem_raw);                 // BR * D
  __half* qbuf = reinterpret_cast<__half*>(acc + BR * D);          // BR * LD
  __half* kvbuf = qbuf + BR * LD;                                  // BK * LD
