    m[tid] = -INFINITY;
    l[tid] = 0.0f;
    alpha[tid] = 0.0f;
  }

  for (int idx = tid; idx < BR * D; idx += THREADS) {
    acc[idx] = 0.0f;
  }
  __syncthreads();

  const size_t bh_stride = static_cast<size_t>(L) * D;

  for (int k0 = 0; k0 < L; k0 += BK) {
    for (int idx = tid; idx < BR * BK; idx += THREADS) {
      p[idx] = 0.0f;
    }
    __syncthreads();

    // scores = Q_tile @ K_tile^T, accumulated over head-dim chunks
    for (int dc = 0; dc < D; dc += CHUNK) {
      for (int idx = tid; idx < BR * CHUNK; idx += THREADS) {
        const int r = idx / CHUNK;
        const int dd = idx - r * CHUNK;
        const size_t go = static_cast<size_t>(bh) * bh_stride +
                          static_cast<size_t>(q0 + r) * D + (dc + dd);
        qbuf[r * LD + dd] = Q[go];
      }
      for (int idx = tid; idx < BK * CHUNK; idx += THREADS) {
        const int j = idx / CHUNK;
        const int dd = idx - j * CHUNK;
        const size_t go = static_cast<size_t>(bh) * bh_stride +
                          static_cast<size_t>(k0 + j) * D + (dc + dd);
        kvbuf[j * LD + dd] = K[go];
      }
      __syncthreads();

