        const int r = idx / BK;
        const int j = idx - r * BK;
        const __half* qptr = qbuf + r * LD;
        const __half* kptr = kvbuf + j * LD;
        float s = 0.0f;
#pragma unroll 4
        for (int dd = 0; dd < CHUNK; dd += 2) {
          const float2 qv = __half22float2(*reinterpret_cast<const __half2*>(qptr + dd));
          const float2 kv = __half22float2(*reinterpret_cast<const __half2*>(kptr + dd));
          s += qv.x * kv.x + qv.y * kv.y;
        }
        p[idx] += s;
      }
      __syncthreads();
    }

    // online softmax update for this key tile
    if (tid < BR) {
      const int base = tid * BK;
      const float old_m = m[tid];
      const float old_l = l[tid];
      float new_m = old_m;
#pragma unroll
      for (int j = 0; j < BK; ++j) {
        const float sc = p[base + j] * scale;
        new_m = sc > new_m ? sc : new_m;
      }
      const float a = (old_l == 0.0f) ? 0.0f : __expf(old_m - new_m);
      float new_l = old_l * a;
#pragma unroll
      for (int j = 0; j < BK; ++j) {
        const float e = __expf(p[base + j] * scale - new_m);
        p[base + j] = e;
        new_l += e;
      }
      m[tid] = new_m;
      l[tid] = new_l;
      alpha[tid] = a;
    }
    __syncthreads();

    for (int idx = tid; idx < BR * D; idx += THREADS) {
      acc[idx] *= alpha[idx / D];
    }
    __syncthreads();

    // acc += P_tile @ V_tile, again chunked over head dim
    for (int dc = 0; dc < D; dc += CHUNK) {
      for (int idx = tid; idx < BK * CHUNK; idx += THREADS) {
        const int j = idx / CHUNK;
        const int dd = idx - j * CHUNK;
        const size_t go = static_cast<size_t>(bh) * bh_stride +
                          static_cast<size_t>(k0 + j) * D + (dc + dd);
        kvbuf[j * LD + dd] = V[go];
      }
      __syncthreads();

      for (int idx = tid; idx < BR * CHUNK; idx += THREADS) {
        const int r = idx / CHUNK;
        const int dd = idx - r * CHUNK;
        const float* prow = p + r * BK;
        const __half* vptr = kvbuf + dd;
        float a = 0.0f;
#pragma unroll 4
        for (int j = 0; j < BK; ++j) {
          a += prow[j] * __half2float(vptr[j * LD]);
        }
        acc[r * D + dc + dd] += a;
      }
      __syncthreads();
    }
  }

  for (int idx = tid; idx < BR * D; idx += THREADS) {
    const int r = idx / D;
    const int d = idx - r * D;
    const float inv_l = 1.0f / l[r];
    const size_t go = static_cast<size_t>(bh) * bh_stride +
                      static_cast<size_t>(q0 + r) * D + d;
    out[go] = __float2half_rn(acc[idx] * inv_l);
  }
